public static void sumLess(int[] arr) {
    Scanner in = new Scanner(System.in);
    int num = in.nextInt();
    int sum = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] < num) {
            sum += arr[i];
        }
    }
    System.out.println(sum);
}

